"""Generate, audit and propose dependency locks without changing an environment.

Requires packaging; lock generation additionally needs the pinned uv executable.
Run from any directory. All writes are limited to the selected repository root
and explicit report/output paths. No installation or Git operation is performed.
"""

import argparse
import fnmatch
import json
import re
import subprocess
import tempfile
import urllib.request
from datetime import UTC, datetime, timedelta
from pathlib import Path

import tomllib
from packaging.markers import default_environment
from packaging.requirements import Requirement
from packaging.specifiers import SpecifierSet
from packaging.utils import canonicalize_name
from packaging.version import InvalidVersion, Version

ROOT = Path(__file__).resolve().parents[1]
GENERATED = (
    "# Generated by python env/dependencies.py refresh; "
    "edit pyproject.toml or env/dependencies.toml.\n"
)
PLATFORMS = {"linux-64": "x86_64-unknown-linux-gnu", "linux-aarch64": "aarch64-unknown-linux-gnu"}


def policy(root):
    return tomllib.loads((root / "env/dependencies.toml").read_text())


def requirements(path, seen=None):
    """Read pinned pip locks, retaining hashes and detecting conflicting includes."""
    seen = set() if seen is None else seen
    path = path.resolve()
    if path in seen:
        raise ValueError(f"Recursive requirements include: {path}")
    seen = seen | {path}
    result = {}
    text = path.read_text().replace("\\\n", " ")
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        if line.startswith("-r "):
            entries = requirements(path.parent / line[3:].strip(), seen)
        elif line.startswith("--"):
            continue
        else:
            req = Requirement(line.split(" --hash=")[0].strip())
            entries = {canonicalize_name(req.name): (req, line)}
        for name, entry in entries.items():
            if name in result and result[name] != entry:
                raise ValueError(f"Conflicting dependency {name} in {path}")
            result[name] = entry
    return result


def exact_version(req):
    specs = list(req.specifier)
    if len(specs) != 1 or specs[0].operator != "==" or "*" in specs[0].version:
        raise ValueError(f"Expected an exact version: {req}")
    return specs[0].version


def declared(root, extras, *, architecture="x86_64"):
    project = tomllib.loads((root / "pyproject.toml").read_text())["project"]
    name = canonicalize_name(project["name"])
    environment = {
        **default_environment(),
        "sys_platform": "linux",
        "platform_system": "Linux",
        "platform_machine": architecture,
        "python_version": policy(root)["python"],
        "python_full_version": policy(root)["python"] + ".0",
    }
    result, visited = {}, set()

    def visit(extra):
        if extra in visited:
            return
        visited.add(extra)
        values = (
            project.get("dependencies", [])
            if extra is None
            else project["optional-dependencies"][extra]
        )
        for value in values:
            req = Requirement(value)
            if req.marker and not req.marker.evaluate({**environment, "extra": extra or ""}):
                continue
            key = canonicalize_name(req.name)
            if key == name:
                for child in sorted(req.extras):
                    visit(child)
            else:
                if req.url:
                    raise ValueError(f"Deployment locks require published packages: {req}")
                result.setdefault(key, []).append(req)

    visit(None)
    for extra in extras:
        visit(extra)
    return result


def pc_input(root):
    config = policy(root)
    deps = declared(root, config["pc_extras"])
    pins = {canonicalize_name(r.name): r for r in map(Requirement, config["pins"])}
    lines = []
    for name in sorted(deps.keys() | pins.keys()):
        declared_specs = deps.get(name, [])
        if name in pins:
            version = exact_version(pins[name])
            if any(version not in r.specifier for r in declared_specs):
                raise ValueError(f"Deployment pin {pins[name]} violates project requirements")
            # An exact project requirement belongs in pyproject.toml alone.
            if any(str(r.specifier) == f"=={version}" for r in declared_specs):
                raise ValueError(f"Redundant deployment pin: {pins[name]}")
            lines.append(str(pins[name]))
        else:
            specs = sorted({str(r.specifier) for r in declared_specs if r.specifier})
            extras = sorted({extra for r in declared_specs for extra in r.extras})
            suffix = f"[{','.join(extras)}]" if extras else ""
            lines.append(name + suffix + ",".join(specs))
    return GENERATED + "\n".join(lines) + "\n"


def check(root):
    expected = pc_input(root)
    if (root / "env/pc-linux-64.in").read_text() != expected:
        raise ValueError("env/pc-linux-64.in is stale; run python env/dependencies.py refresh")
    pc = requirements(root / "env/pc-linux-64.lock")
    roles = [("pc-linux-64", declared(root, policy(root)["pc_extras"]))]
    roles += [
        (f"host-{arch}", declared(root, ["host"], architecture=machine))
        for arch, machine in (("linux-64", "x86_64"), ("linux-aarch64", "aarch64"))
    ]
    for role, deps in roles:
        locked = requirements(root / f"env/{role}.lock")
        for name, (req, line) in locked.items():
            exact_version(req)
            if not re.search(r"--hash=sha256:[0-9a-f]{64}(?:\s|$)", line):
                raise ValueError(f"Missing SHA256 for {name} in {role}")
        for name, constraints in deps.items():
            if name not in locked:
                raise ValueError(f"Missing {name} in {role}")
            version = exact_version(locked[name][0])
            if any(version not in req.specifier for req in constraints):
                raise ValueError(f"{role}: {name}=={version} violates project requirements")
        if role.startswith("host-"):
            forbidden = {"torch", "transformers", "pynput", "lerobot", "datasets"}
            if locked.keys() & forbidden:
                raise ValueError(f"Host contains PC dependencies: {locked.keys() & forbidden}")
            for name in locked.keys() & pc.keys():
                if exact_version(locked[name][0]) != exact_version(pc[name][0]):
                    raise ValueError(f"PC/Host version mismatch: {name}")
    for name, (req, _) in requirements(root / "env/pc-linux-64.in").items():
        if name not in pc or exact_version(pc[name][0]) not in req.specifier:
            raise ValueError(f"PC lock does not satisfy {req}")


def dependency_group(name, groups):
    return next(
        group
        for group, patterns in groups.items()
        if any(fnmatch.fnmatchcase(name, pattern) for pattern in patterns)
    )


def latest_release(metadata, current, python, cutoff):
    """Select stable, non-yanked releases in the current major, after cooldown."""
    current = Version(current)
    candidates = [current]
    for value, files in metadata["releases"].items():
        try:
            version = Version(value)
        except InvalidVersion:
            continue
        if (
            version <= current
            or version.major != current.major
            or version.is_prerelease
            or version.is_devrelease
        ):
            continue
        eligible = [
            f
            for f in files
            if not f.get("yanked")
            and python in SpecifierSet(f.get("requires_python") or "")
            and datetime.fromisoformat(f["upload_time_iso_8601"].replace("Z", "+00:00")) <= cutoff
        ]
        if eligible:
            candidates.append(version)
    return str(max(candidates))


def propose(root, group, *, fetch=None):
    config = policy(root)
    locked = requirements(root / "env/pc-linux-64.lock")
    files = [root / "pyproject.toml", root / "env/dependencies.toml"]
    contents = {p: p.read_text() for p in files}
    cutoff = datetime.now(UTC) - timedelta(days=config["cooldown_days"])
    changes = []
    for name, (req, _) in sorted(locked.items()):
        if dependency_group(name, config["groups"]) != group:
            continue
        # Only replace declarations that pin this package. Ranged/transitive
        # packages are resolved by uv, using the existing lock as its preference.
        pattern = rf'(["\'])({re.escape(name)}==)([^"\']+)(["\'])'
        matches = [m for content in contents.values() for m in re.finditer(pattern, content)]
        if not matches:
            continue
        if fetch is None:
            with urllib.request.urlopen(
                f"https://pypi.org/pypi/{name}/json", timeout=30
            ) as response:
                metadata = json.load(response)
        else:
            metadata = fetch(name)
        old = exact_version(req)
        new = latest_release(metadata, old, config["python"] + ".0", cutoff)
        if new == old:
            continue
        for p, content in contents.items():
            contents[p] = re.sub(pattern, lambda m, v=new: m[1] + m[2] + v + m[4], content)
        changes.append({"package": name, "old": old, "new": new})
    for path, content in contents.items():
        path.write_text(content)
    return changes


def compile_lock(
    root, source, output, *, architecture="linux-64", group=None, cpu=False, constraint=None
):
    config = policy(root)
    command = [
        "uv",
        "pip",
        "compile",
        str(source),
        "--output-file",
        str(output),
        "--python-version",
        config["python"],
        "--python-platform",
        PLATFORMS[architecture],
        "--generate-hashes",
        "--no-header",
        "--no-annotate",
        "--emit-build-options",
        "--only-binary",
        ":all:",
        "--no-binary",
        "feetech-servo-sdk",
        "--no-binary",
        "evdev",
        "--no-binary",
        "docopt",
    ]
    if output.exists():
        # Preserve version preferences, but supply build options once below.
        text = (
            "\n".join(line for line in output.read_text().splitlines() if not line.startswith("--"))
            + "\n"
        )
        output.write_text(text)
    if constraint:
        command += ["--constraint", str(constraint)]
    if cpu:
        command += ["--torch-backend", "cpu"]
    if group:
        existing = requirements(root / "env/pc-linux-64.lock")
        for name in existing:
            if dependency_group(name, config["groups"]) == group:
                command += ["--upgrade-package", name]
        command += [
            "--exclude-newer",
            (datetime.now(UTC) - timedelta(days=config["cooldown_days"])).isoformat(),
            "--prerelease",
            "disallow",
        ]
    with tempfile.TemporaryDirectory(prefix="alohamini-version-bounds-") as directory:
        if group:
            # Apply the major-version policy to transitive dependencies too.
            bounds = Path(directory) / "bounds.in"
            bounds.write_text(
                "\n".join(
                    f"{name}<{Version(exact_version(req)).major + 1}"
                    for name, (req, _) in sorted(existing.items())
                )
                + "\n"
            )
            command += ["--constraint", str(bounds)]
        subprocess.run(command, cwd=root, check=True, stdout=subprocess.DEVNULL)
    # Constraints can repeat build options. Keep regeneration idempotent.
    lines, options = [], set()
    for line in output.read_text().splitlines():
        if line.startswith("--"):
            if line in options:
                continue
            options.add(line)
        lines.append(line)
    output.write_text("\n".join(lines) + "\n")


def refresh(root, *, group=None):
    paths = [
        root / "pyproject.toml",
        root / "env/dependencies.toml",
        root / "env/pc-linux-64.in",
        *sorted((root / "env").glob("*.lock")),
    ]
    originals = {path: path.read_bytes() for path in paths}
    try:
        _refresh(root, group=group)
    except BaseException:
        for path, content in originals.items():
            path.write_bytes(content)
        raise


def _refresh(root, *, group=None):
    if group:
        propose(root, group)
    (root / "env/pc-linux-64.in").write_text(pc_input(root))
    compile_lock(root, root / "env/pc-linux-64.in", root / "env/pc-linux-64.lock", group=group)
    pc = requirements(root / "env/pc-linux-64.lock")
    with tempfile.TemporaryDirectory(prefix="alohamini-host-lock-") as directory:
        directory = Path(directory)
        hardware = None
        for arch, machine in (("linux-64", "x86_64"), ("linux-aarch64", "aarch64")):
            direct = declared(root, ["host"], architecture=machine)
            source, output = directory / f"{arch}.in", directory / f"{arch}.lock"
            source.write_text(
                "\n".join(f"{name}=={exact_version(pc[name][0])}" for name in sorted(direct)) + "\n"
            )
            compile_lock(root, source, output, architecture=arch)
            entries = requirements(output)
            shared = (
                "\n".join(entries[name][1] for name in ("feetech-servo-sdk", "pyserial")) + "\n"
            )
            if hardware is not None and hardware != shared:
                raise ValueError("Hardware lock is not architecture independent")
            hardware = shared
            (root / f"env/runtime-{arch}.lock").write_text(
                GENERATED + "--only-binary=:all:\n" + entries["pyzmq"][1] + "\n"
            )
            body = [
                entry[1]
                for name, entry in sorted(entries.items())
                if name not in ("pyzmq", "feetech-servo-sdk", "pyserial")
            ]
            (root / f"env/host-{arch}.lock").write_text(
                GENERATED
                + f"-r runtime-{arch}.lock\n-r hardware.lock\n--no-binary=feetech-servo-sdk\n"
                + "\n".join(body)
                + "\n"
            )
        (root / "env/hardware.lock").write_text(GENERATED + hardware)
    (root / "env/dev-linux-64.lock").write_text(
        GENERATED + "-r runtime-linux-64.lock\n" + pc["ruff"][1] + "\n"
    )
    check(root)


def write_report(before, root, output):
    after = requirements(root / "env/pc-linux-64.lock")
    rows = []
    for name in sorted(before.keys() | after.keys()):
        old = exact_version(before[name][0]) if name in before else "—"
        new = exact_version(after[name][0]) if name in after else "—"
        if old != new:
            rows.append(f"| {name} | {old} | {new} |")
    text = "Dependency candidate generated from the current main branch.\n\n"
    text += "| Package | Previous | Candidate |\n| --- | --- | --- |\n" + "\n".join(rows)
    text += (
        "\n\nCPU checks run on the candidate commit. Model/compute updates also require "
        "the manually triggered GPU validation and checkpoint comparison before acceptance.\n"
    )
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(text)


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("command", choices=("check", "inputs", "refresh", "ci-lock"))
    parser.add_argument("--root", type=Path, default=ROOT)
    parser.add_argument("--group", choices=tuple(policy(ROOT)["groups"]))
    parser.add_argument("--output", type=Path)
    parser.add_argument("--report", type=Path)
    args = parser.parse_args(argv)
    root = args.root.resolve()
    if args.command == "check":
        check(root)
        print("PASS: project requirements, generated inputs, hashes and PC/Host locks")
    elif args.command == "inputs":
        (root / "env/pc-linux-64.in").write_text(pc_input(root))
    elif args.command == "ci-lock":
        if args.output is None:
            parser.error("ci-lock requires --output")
        args.output.parent.mkdir(parents=True, exist_ok=True)
        compile_lock(
            root,
            root / "env/pc-linux-64.in",
            args.output,
            cpu=True,
            constraint=root / "env/pc-linux-64.lock",
        )
    else:
        before = requirements(root / "env/pc-linux-64.lock")
        refresh(root, group=args.group)
        if args.report:
            write_report(before, root, args.report)


if __name__ == "__main__":
    main()
